package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.model.LmdbValue;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class LmdbGcBatchingCompatibilityTest {
	@TempDir
	Path directory;

	@Test
	void diskBackedCandidatesUseBoundedLivenessProbesAndProtectNestedOwners() throws Exception {
		Path dictionary = Files.createDirectories(directory.resolve("dictionary"));
		Path scratch = Files.createDirectories(directory.resolve("scratch"));
		ValueStore values = new ValueStore(dictionary.toFile(), new LmdbStoreConfig().setInlineLiterals(false));
		PersistentSetFactory<Long> factory = new PersistentSetFactory<>(scratch.toFile());
		try {
			var vf = SimpleValueFactory.getInstance();
			var literal = vf.createLiteral("protected nested component", vf.createIRI("urn:batch:datatype"));
			var inner = vf.createTripleTerm(vf.createIRI("urn:batch:inner"), vf.createIRI("urn:batch:p"), literal);
			var outer = vf.createTripleTerm(vf.createIRI("urn:batch:outer"), vf.createIRI("urn:batch:p"), inner);
			values.startTransaction(true);
			long outerId = values.storeValue(outer);
			long innerId = values.getId(inner);
			long literalId = values.getId(literal);
			values.commit();
			AtomicInteger checks = new AtomicInteger();
			values.completeStoreInitialization(candidates -> {
				assertTrue(candidates.size() <= 4096, "Every statement-liveness probe must remain bounded");
				checks.incrementAndGet();
			}, new HashSet<>(), new HashSet<>());
			PersistentSet<Long> ids = factory.createSet("candidates",
					id -> ByteBuffer.allocate(Long.BYTES).order(ByteOrder.BIG_ENDIAN).putLong(id).array(),
					buffer -> buffer.order(ByteOrder.BIG_ENDIAN).getLong());
			for (long ordinal = 10000; ordinal < 20000; ordinal++) {
				ids.add(ValueIds.createId(ValueIds.T_URI, ordinal));
			}
			ids.add(innerId);
			ids.add(literalId);
			assertEquals(10002, ids.size());
			var expectedRoundTrips = new HashSet<>(List.of(innerId, literalId,
					ValueIds.createId(ValueIds.T_URI, 10000), ValueIds.createId(ValueIds.T_URI, 19999)));
			for (long candidate : ids) {
				expectedRoundTrips.remove(candidate);
			}
			assertTrue(expectedRoundTrips.isEmpty(), "Scratch iteration must preserve the actual candidate IDs");
			try (var files = Files.walk(scratch)) {
				assertTrue(files.anyMatch(file -> file.getFileName().toString().equals("data.mdb")),
						"Candidates must use the real disk-backed worklist abstraction");
			}
			values.startTransaction(true);
			values.gcIds(ids, new HashSet<>());
			values.commit();
			assertTrue(checks.get() >= 3);
			assertEquals(outer, values.getValue(outerId));
			assertEquals(literal, values.getValue(literalId));
		} finally {
			values.rollback();
			values.close();
			factory.close();
		}
	}

	@Test
	void duplicateCandidatesAcrossBatchBoundariesDoNotDeleteSharedDependenciesTwice() throws Exception {
		ValueStore values = new ValueStore(directory.toFile(), new LmdbStoreConfig().setInlineLiterals(false));
		try {
			var vf = SimpleValueFactory.getInstance();
			var datatype = vf.createIRI("urn:duplicate:datatype");
			var removed = vf.createLiteral("remove", datatype);
			var live = vf.createLiteral("retain", datatype);
			values.startTransaction(true);
			long removedId = values.storeValue(removed);
			long liveId = values.storeValue(live);
			values.commit();
			values.completeStoreInitialization(candidates -> {
				assertTrue(candidates.size() <= 4096);
				candidates.remove(liveId);
			}, new HashSet<>(), new HashSet<>());
			var ids = new ArrayList<Long>();
			ids.add(removedId);
			for (long ordinal = 10000; ordinal < 20000; ordinal++) {
				ids.add(ValueIds.createId(ValueIds.T_URI, ordinal));
			}
			ids.add(removedId);
			ids.add(liveId);
			values.startTransaction(true);
			values.gcIds(ids, new HashSet<>());
			values.commit();
			assertEquals(LmdbValue.UNKNOWN_ID, values.getId(removed));
			assertEquals(live, values.getValue(liveId));
			assertEquals(datatype, values.getValue(values.getId(datatype)));
		} finally {
			values.rollback();
			values.close();
		}
	}
}
